export const S_SURGERY = "Breast-conserving surgery or mastectomy";
export const S_RECONSTRUCTION = "Reconstruction surgery, delayed reconstruction, or neither";
export const S_AXILLA = "Surgery to the armpit, and the lymphoedema risk that lasts for life";
export const S_FERTILITY = "Fertility and early menopause, decided before treatment starts";
export const S_BODY = "Body image, sensation and sex";
