// ---------------------------------------------------------------- questions (settings above, then by appointment)
export const breastQuestions: Question[] = [
  { setting: "Newly diagnosed", question: "Which type of breast cancer is this: hormone receptor-positive, HER2-positive, triple-negative, or are we still waiting?", why: "NICE NG101 (1.3.1) says to assess the oestrogen receptor, progesterone receptor and HER2 status of all invasive breast cancers simultaneously at the time of initial histopathological diagnosis. Almost every drug decision follows from that result, and the pages for each type carry the detail." },
  { setting: "Newly diagnosed", question: "Who is my breast care nurse or key worker, and what is the number for the team between appointments and out of hours?", why: "NICE NG101 (1.1.1) says to ensure all people with breast cancer have a named clinical nurse specialist, or other specialist key worker with equivalent skills, to support them throughout diagnosis, treatment and follow-up." },
  { setting: "Newly diagnosed", question: "What is the plan, in order, and which parts of it are decided and which are still choices for me?", why: "The decisions that are yours are not the same as the ones that are clinical. NICE NG101 (1.4.6) sends the further-surgery conversation to its own guidelines on shared decision making and on patient experience, which ask that risks, benefits and consequences are communicated and that you take an active part." },
  { setting: "Newly diagnosed", question: "Can I be referred for psychological support, and is there a Maggie's centre or a peer support service near me?", why: "NICE NG101 (1.1.2) says to offer all people with breast cancer prompt access to specialist psychological support and, where appropriate, psychiatric services. Maggie's centres are free and need no appointment." },
  { setting: "Newly diagnosed", question: "Is there a clinical trial open to me here or at another hospital?", why: "NICE NG101 (1.1.4) says to discuss opportunities for people with breast cancer to be involved in research, and encourage entry into clinical trials and other studies. The NHS says you can leave a trial at any point without giving a reason." },

  { setting: S_SURGERY, question: "Am I suitable for breast-conserving surgery, and if you are recommending a mastectomy, which of the reasons applies to me?", why: "Macmillan says surgeons try to do an operation that means you can keep your breast, and lists the reasons a mastectomy may be recommended instead: the lump is large compared to the rest of your breast, there is cancer in different parts of the breast, there is widespread DCIS, the cancer is on the skin or in underlying muscle, you have had radiotherapy to the chest before, or you have tested positive for a gene mutation." },
  { setting: S_SURGERY, question: "If I choose conserving surgery, how many radiotherapy sessions would I have, and would a mastectomy avoid radiotherapy in my case?", why: "NICE NG101 (1.13.3) says to offer whole-breast radiotherapy after breast-conserving surgery with clear margins, and (1.13.13) 26 Gy in 5 fractions over 1 week where no lymph node irradiation is needed. But NG101 (1.13.10) also says to offer radiotherapy after mastectomy to people with node-positive disease or involved margins, so a mastectomy does not always avoid it." },
  { setting: S_SURGERY, question: "What is the chance I would need a second operation because the margins are not clear, and what is this unit's rate?", why: "NICE NG101 (1.4.3) says to offer further surgery where cancer is present at the radial margins, and (1.4.5) to consider it where tumour cells are within 1 mm. The 2024 committee noted that rates of further surgery currently vary across the country, and moved the threshold from 2 mm to 1 mm partly to reduce additional surgeries." },
  { setting: S_SURGERY, question: "What will the breast look and feel like afterwards, and can I see photographs?", why: "Cancer Research UK says surgeons can show you pictures of different results straight after surgery and several months later, and that scars fade but it may take up to a year for things to settle. If a large amount of tissue is removed the breast may be left with a dent, and partial reconstruction or reshaping may be possible." },
  { setting: S_SURGERY, question: "If the cancer came back in the same breast, what would happen then?", why: "This is the question the survival figures do not answer. In the Milan trial, 30 of 352 women treated with quadrantectomy and radiotherapy had a recurrence in the same breast over 20 years, against 8 local recurrences among 349 treated by radical mastectomy, while deaths from all causes were 41.2 and 41.7 percent with no significant difference." },

  { setting: S_RECONSTRUCTION, question: "Can I see an oncoplastic or plastic surgeon before I decide, and can I have immediate reconstruction even though I may need radiotherapy?", why: "NICE NG101 (1.5.4) says to offer immediate breast reconstruction to women who have been advised to have a mastectomy, including those who may need radiotherapy, unless they have comorbidities that rule out reconstructive surgery, and (1.5.3) to offer both immediate and delayed options whether or not they are available locally." },
  { setting: S_RECONSTRUCTION, question: "For each type you are offering, how many operations would it take, how long is the recovery, and what does it take from the rest of my body?", why: "NICE NG101 table 1 says more than 1 operation is usually needed to complete a reconstruction, whether immediate or delayed. Cancer Research UK says recovery is longer after reconstruction than after mastectomy alone, that a flap uses skin, fat or muscle from elsewhere, and that you may have more scars on your body." },
  { setting: S_RECONSTRUCTION, question: "What happens if the reconstruction fails or gets infected, and could that delay my chemotherapy or radiotherapy?", why: "NICE NG101 table 1 lists flap or implant failure, which may lead to delayed reconstruction and a flat appearance for a period of time, and says radiotherapy or chemotherapy may be delayed if there are complications. Cancer Research UK says there is good research evidence that chemotherapy works best if you start it within 6 weeks of cancer surgery." },
  { setting: S_RECONSTRUCTION, question: "Is going flat a proper option here, and can you make the chest wall flat and even rather than leaving loose skin?", why: "NICE NG101 (1.5.2) says to be aware that some people may prefer not to have breast reconstruction surgery. Cancer Research UK says your surgeon might be able to improve the appearance of the chest with more surgery after mastectomy, and that a prosthesis is an alternative to reconstruction." },
  { setting: S_RECONSTRUCTION, question: "Would I need surgery on the other breast to match, and when would that be?", why: "Cancer Research UK says some people need contralateral symmetrisation surgery to make the other breast bigger, smaller or less droopy, and that this can be done at the same time or later." },

  { setting: S_AXILLA, question: "Which armpit operation am I having, and why that one?", why: "NICE NG101 (1.4.9) says to stage the axilla with sentinel lymph node biopsy rather than axillary lymph node clearance where the ultrasound shows no involvement or a needle biopsy was negative, and (1.4.11) to offer clearance where a preoperative needle biopsy proved lymph node metastases." },
  { setting: S_AXILLA, question: "If a sentinel node has cancer in it, what happens next, and is radiotherapy to the armpit an option instead of clearance?", why: "NICE NG101 (1.4.12) says to offer further axillary treatment, clearance or radiotherapy, after a sentinel node biopsy showing 1 or more macrometastasis, and (1.4.13) to discuss the benefits and risks of not having further treatment with women who have 1 or 2 macrometastases and have been advised to have whole-breast radiotherapy with systemic therapy. In AMAROS, lymphoedema at 5 years was 24.5 percent after clearance against 11.9 percent after axillary radiotherapy." },
  { setting: S_AXILLA, question: "What is my personal lymphoedema risk after the operation you are proposing, and will someone measure my arm before surgery?", why: "NICE NG101 (1.14.1) says to inform people about their risk of lymphoedema before treatment starts, in a format to take away, including how to self-monitor and how to collect baseline measurements of the limb. In the pooled prospective cohorts of the DiSipio meta-analysis the overall incidence was 21.4 percent, about four times higher after axillary clearance (19.9 percent) than after sentinel node biopsy (5.6 percent)." },
  { setting: S_AXILLA, question: "Am I high risk for shoulder problems, and can I have supervised physiotherapy rather than a leaflet?", why: "NICE NG101 (1.14.14) names pre-existing shoulder conditions, a BMI over 30, planned axillary node clearance and planned radiotherapy to the axilla or supraclavicular nodes as high-risk factors, and (1.14.16) says to offer supervised support with upper limb exercises to people identified as high risk." },
  { setting: S_AXILLA, question: "What are the early signs of lymphoedema, and who do I ring if I see them?", why: "NICE NG101 (1.14.6) says to refer people who develop lymphoedema to a specialist lymphoedema service as soon as possible. Breast Cancer Now lists the early signs as swelling that may come and go and be worse at the end of the day, tightness in the arm or breast, a dull ache, heaviness, tingling or numbness, and dry skin." },

  { setting: S_FERTILITY, question: "Is the treatment you are planning likely to affect my fertility, and can I be referred to a fertility clinic this week?", why: "NICE NG257 (1.53.1) says to discuss fertility preservation with people preparing for medical treatment likely to impair their fertility, and that for people who need urgent treatment this discussion should take place at the earliest possible opportunity. Cancer Research UK says egg freezing takes about 2 to 3 weeks." },
  { setting: S_FERTILITY, question: "Is fertility preservation funded for me on the NHS, and does my age or whether I already have children affect that?", why: "NICE NG257 (1.53.3) says that for NHS-funded fertility preservation, do not apply the eligibility criteria used for conventional fertility treatment, including the lower age limit, and (1.53.4) that those criteria will apply when it comes to using the stored material. Cancer Research UK says IVF is available for some people on the NHS but not in all parts of the country." },
  { setting: S_FERTILITY, question: "Would injections to switch off my ovaries during chemotherapy help, and what would that add?", why: "In an individual patient-level meta-analysis of 873 patients from five trials, premature ovarian insufficiency occurred in 14.1 percent of those given a GnRH agonist with chemotherapy against 30.9 percent of controls, and post-treatment pregnancy in 10.3 percent against 5.5 percent, with no significant difference in disease-free or overall survival. In POEMS, which enrolled 257 premenopausal women with operable hormone receptor-negative breast cancer, ovarian failure at 2 years was 8 percent with goserelin against 22 percent." },
  { setting: S_FERTILITY, question: "If treatment brings on the menopause, what can I be offered for the symptoms, given that HRT is usually ruled out?", why: "NICE NG101 (1.14.22) says not to routinely offer HRT to women with menopausal symptoms and a history of breast cancer, (1.14.23) to offer it in exceptional circumstances for severe symptoms after discussing the risks, (1.14.24) to consider an SSRI for hot flushes but not for those taking tamoxifen, and (1.14.25) not to offer soy, red clover, black cohosh, vitamin E or magnetic devices." },
  { setting: S_FERTILITY, question: "Should I have a bone density scan?", why: "NICE NG101 (1.14.26) says to offer a baseline DEXA scan to women with invasive breast cancer who are not on adjuvant bisphosphonates and who are starting an aromatase inhibitor, have treatment-induced menopause, or are starting ovarian ablation or suppression, and (1.14.27) not to offer one to people receiving tamoxifen alone." },

  { setting: S_BODY, question: "Which part of my chest, breast or arm will be numb afterwards, and will the feeling come back?", why: "Cancer Research UK says you might have numbness, tingling or a shooting pain in the armpit, upper arm, shoulder or chest wall from nerve damage during surgery, and that nerves usually repair themselves but it can take many weeks or months. In a Danish national survey of 3,253 women a median of 26 months after surgery, the odds of sensory disturbance were about five times higher after axillary clearance than after sentinel node dissection." },
  { setting: S_BODY, question: "Will a reconstructed breast or a spared nipple have any feeling?", why: "Cancer Research UK says the new breast will feel and look different to the one removed, and that surgeons aim to match the other breast but it will not be identical. Asking specifically about sensation, rather than about appearance, is how this gets answered before rather than after the operation." },
  { setting: S_BODY, question: "I want to talk about sex. Who here does that, and can my partner come?", why: "Cancer Research UK says breast surgery does not affect being able to have sex but that emotions might change sexual feelings for a while, and that you might worry about allowing a partner to see or touch your body. NICE NG101 (1.1.2) puts prompt access to specialist psychological support in the guideline rather than leaving it to chance." },
  { setting: S_BODY, question: "If treatment causes vaginal dryness or pain, what can I use, given that I am being told to avoid hormones?", why: "Cancer Research UK's menopausal symptoms page covers this, and NICE NG101 (1.14.20) asks that women are offered information and counselling about the possibility of early menopause and menopausal symptoms associated with breast cancer treatment. Dryness is a treatable symptom rather than something to put up with." },
  { setting: S_BODY, question: "Is there a prosthesis fitting service, specialist bras, and someone who has been through this that I could talk to?", why: "Cancer Research UK lists mastectomy wear and prosthesis suppliers and says it can take time to adjust to a new body shape. Breast Cancer Now's Someone Like Me service pairs people with a volunteer who has had a similar experience." },

  { setting: S_HAIR, question: "Will the drugs you are giving me cause hair loss, and when would it start?", why: "Macmillan says hair loss usually starts after the first or second treatment and that eyebrows and eyelashes can go too. Which drug matters: not all breast cancer treatment causes it, and the pages for each receptor type list the regimens." },
  { setting: S_HAIR, question: "Is scalp cooling available in this unit, how much longer does each session take, and how well does it work with my regimen?", why: "In the SCALP randomised trial, 50.5 percent of women cooled during taxane, anthracycline or both kept more than half their hair after the fourth cycle, against none of the controls. Cooling adds time before and after each infusion, so the practical question is how long a treatment day becomes." },
  { setting: S_HAIR, question: "Does scalp cooling work as well for my hair type?", why: "A phase II study of Paxman scalp cooling in Black patients receiving chemotherapy for stage I to III breast cancer closed early after 15 of a planned 30 participants, for lack of efficacy: only one participant avoided significant hair loss, and the authors concluded that scalp cooling may not be efficacious in preventing alopecia in Black women, pointing to hair thickness, hair volume and cap design." },
  { setting: S_HAIR, question: "If I want a wig, when should I get it, and what help is there with the cost?", why: "Macmillan says it is a good idea to get a wig before treatment starts, because it is easier to match your own hair colour and style and you can get used to wearing it, and that the Little Princess Trust provides free real-hair wigs to young people up to age 24 who have hair loss as a result of cancer treatment." },

  { setting: S_FOLLOWUP, question: "What does my follow-up look like: how often, with whom, and which scans?", why: "NICE NG101 (1.15.1) says to offer annual mammography for 5 years to all people who have had or are being treated for breast cancer, including DCIS, continuing past 5 years for women until they enter the NHS Breast Screening Programme or Breast Test Wales, and (1.15.3) not to routinely use ultrasound or MRI for post-treatment surveillance. NICE reviewed NG101 on 11 September 2026 and says the annual mammography recommendation is one it will be updating, so this is the part of follow-up most likely to change." },
  { setting: S_FOLLOWUP, question: "Can I have my written care plan, with the signs to look out for and the number to ring?", why: "NICE NG101 (1.15.4) says to ensure everyone who has had treatment has an agreed, written care plan recorded in their notes, with a copy for them and their GP, naming the healthcare professionals, the dates for reviewing adjuvant therapy, the surveillance mammography, the signs and symptoms to look out for and seek advice on, and contact details for immediate referral and for support services such as lymphoedema." },
  { setting: S_FOLLOWUP, question: "Which symptoms should make me ring rather than wait for the next appointment?", why: "Breast Cancer Now says to talk to your GP or breast care nurse about any symptom that is new, does not have an obvious cause, and does not go away, and that this applies whether or not you have already been diagnosed with secondary breast cancer." },
  { setting: S_FOLLOWUP, question: "Does this unit audit its recurrence rates, and can I see them?", why: "NICE NG101 (1.4.16) says all breast units should audit their local, regional and distant recurrence rates after treatment, including systematically collecting data on radial margins and demographic information, and (1.4.17) that breast units should audit their axillary recurrence rates. It is a fair thing to ask about." },

  { setting: "Surgeon appointment", question: "Which operation do you recommend for me, and what would change your recommendation?", why: "Macmillan says the choice between conserving surgery and mastectomy depends on the size and position of the cancer and the size of the breast, and NICE NG101 (1.4.6) sends this conversation to its shared decision making guideline." },
  { setting: "Surgeon appointment", question: "How long will I be in hospital, when can I drive, lift and go back to work, and will I have drains?", why: "Cancer Research UK says many people have breast surgery as a day case or go home the following day, and that a reconstruction at the same time usually means 2 to 7 days in hospital." },
  { setting: "Surgeon appointment", question: "What can I do in the weeks before the operation to recover better?", why: "Cancer Research UK describes prehabilitation, and says there is a higher risk of complications from breast reconstruction if you smoke, are very overweight or have other serious medical conditions, and that stopping smoking, keeping a healthy weight and staying active before surgery help." },
  { setting: "Breast care nurse appointment", question: "What is the 24-hour number, and what temperature or symptom means I use it?", why: "Macmillan says to contact the 24-hour helpline straight away for a temperature over 37.5 C or below 36 C, for shivering, or for feeling unwell even with a normal temperature, and to call sooner rather than later." },
  { setting: "Breast care nurse appointment", question: "Can I have the arm and shoulder exercises before the operation rather than after?", why: "NICE NG101 (1.14.13) says to give people who are going to have surgery or radiotherapy instructions and information on upper limb exercises before their treatment begins, explaining the benefits, when to start, and who to contact for more information." },
  { setting: "Breast care nurse appointment", question: "What help is there with work, sick pay and money, and how do I ask for it?", why: "Macmillan says the Equality Act 2010 protects people with cancer from being treated less favourably, that employers cannot make reasonable adjustments unless they know, and that its money advisers give free confidential advice on benefits and grants." },
  { setting: "Oncologist appointment", question: "What is the aim of the treatment you are proposing, and how much does each part add?", why: "Macmillan's questions page says to ask what the aim of treatment is, what it involves, and what the benefits and risks are, so that you can weigh each part rather than accept the plan as a single block." },
  { setting: "Oncologist appointment", question: "Which side effects are likely for me, which are permanent, and which have a treatment of their own?", why: "The distinction matters more than the list: NICE NG101 has a named offer for several of them, including an SSRI for hot flushes, a DEXA scan and bone treatment where the menopause is treatment-induced, and supervised physiotherapy for shoulder problems." },
  { setting: "Oncologist appointment", question: "How will we know it is working, and what happens if it is not?", why: "Knowing the plan for the next step helps you weigh the current one, and Macmillan's questions page lists this among the questions worth asking before you agree to treatment." },
  { setting: "Radiotherapy planning appointment", question: "How many sessions, over how many weeks, and to which areas?", why: "NICE NG101 (1.13.13) says to offer 26 Gy in 5 fractions over 1 week for partial-breast, whole-breast or chest-wall radiotherapy without regional lymph node irradiation, (1.13.14) to consider 40 Gy in 15 fractions over 3 weeks in named circumstances including implant-based reconstruction, and (1.13.16) to offer 40 Gy in 15 fractions where the lymph nodes are being treated." },
  { setting: "Radiotherapy planning appointment", question: "Will I be asked to hold my breath, and what is being done to keep the dose off my heart and lung?", why: "NICE NG101 (1.13.1) says to use a radiotherapy technique that minimises the dose to the lung and heart, and (1.13.2) to use a deep inspiratory breath-hold technique for people with left-sided breast cancer to reduce the dose to the heart." },
  { setting: "Radiotherapy planning appointment", question: "How is my skin likely to react, and at what point do I ring about it?", why: "Cancer Research UK describes the skin changes during and after breast radiotherapy and when they settle; asking for the threshold in advance turns a worrying change into a planned phone call." },
  { setting: "Fertility appointment", question: "Which option fits the time we have: egg freezing, embryo freezing, or ovarian tissue?", why: "NICE NG257 (1.53.6) says to offer oocyte or embryo cryopreservation as appropriate to people of reproductive age preparing for treatment likely to make them infertile, and (1.53.7) to consider ovarian tissue cryopreservation when that is not feasible." },
  { setting: "Fertility appointment", question: "How long will my material be stored, who pays, and what happens at review?", why: "NICE NG257 (1.53.8) says to organise follow-ups at least every 5 years with people who have had material preserved to determine whether there is a need to continue NHS-funded storage, and to offer continued NHS-funded storage for people who remain at continued significant risk of infertility." },
  { setting: "Fertility appointment", question: "What contraception should I use during treatment, and for how long afterwards?", why: "Cancer Research UK says it is important to avoid pregnancy during and shortly after treatment for breast cancer and to use reliable contraception as soon as you start treatment." },
  { setting: "Lymphoedema service appointment", question: "What is my baseline measurement, and how do I monitor it myself?", why: "NICE NG101 (1.14.1) asks that the information given before treatment includes how to self-monitor and identify early signs and symptoms, and how to collect baseline measurements of the limb." },
  { setting: "Lymphoedema service appointment", question: "What treatment am I being offered, and what does the daily routine look like?", why: "NICE NG101 (1.14.9) says to offer compression therapy as the first stage of lymphoedema management and to make a shared decision about the form of compression, and (1.14.10) that kinesiology tape may be tried if compression is not appropriate or not comfortable. The NHS describes decongestive lymphatic therapy as compression, skin care, exercise and specialised massage." },
  { setting: "Lymphoedema service appointment", question: "Can I still exercise, fly, have blood taken from that arm or have a manicure?", why: "NICE NG101 (1.14.3) says to ensure people are aware that physical activity may improve quality of life and that there is no indication it causes or worsens lymphoedema, and (1.14.1) that there is no consistent evidence of increased risk associated with air travel, travel to hot countries, manicures, hot tub use, sports injuries, or with medical procedures such as blood tests, injections and blood pressure measurement on the treated side." },
  { setting: "For partners and carers", question: "How do I get included in appointments and get a copy of the plan and the medicine list?", why: "Macmillan says to tell the healthcare team you are a carer so you can be part of the plans, and that driving someone to appointments counts as caring." },
  { setting: "For partners and carers", question: "What are the signs of sepsis, of an infected arm and of cord compression, and what do I do for each?", why: "The NHS sepsis page gives the 999 signs, the NHS cellulitis page gives the urgent GP and 111 threshold for skin that is painful, hot and swollen, and NICE NG234 treats new leg weakness, numbness or loss of bladder or bowel control in anyone with a cancer diagnosis as an oncological emergency." },
  { setting: "For partners and carers", question: "What support is there for me: a carer's assessment, Carer's Allowance, or someone to talk to?", why: "The NHS says a carer's assessment is free and separate from the assessment of the person you care for, and lists the benefits that may apply to carers." },
];

// ---------------------------------------------------------------- glossary terms this layer owns
/**
 * Six terms, all checked against the corpus before they were written. The breast-wide living-with terms the
 * triple-negative layer already owns (hair loss and scalp cooling, menopause after chemotherapy, body image,
 * neutropenic sepsis, work and money, carers) are supplemented below rather than written a second time.
 */
const term = (x: Omit<TermInput, "kind" | "asOf">): TermInput => ({ kind: "term", asOf, cancers: [CANCER], ...x });
export const breastLivingTerms: TermInput[] = [
  term({ id: "lymphoedema-after-breast-cancer", category: "Side effects", name: "Lymphoedema after breast cancer treatment", aka: ["breast cancer-related lymphoedema", "arm swelling after breast surgery", "BCRL"],
    tldr: "Swelling of the arm, hand, breast or chest wall caused by lymph fluid that can no longer drain, after the lymph nodes under the arm have been removed or irradiated. It can start months or years later, it is controlled rather than cured, and the earlier it is treated the better it goes.",
    summary: `In the pooled prospective cohorts of a meta-analysis of 72 studies, 21.4 percent of women developed arm lymphoedema after breast cancer, about four times more often after axillary lymph node dissection (19.9 percent) than after sentinel node biopsy (5.6 percent); the incidence rose over the first two years, and the risk factors with the strongest evidence were extensive surgery and being overweight or obese. Breast Cancer Now says the swelling may come and go at first and be worse at the end of the day, and that tightness, a dull ache, heaviness, tingling, numbness or dry skin can come before any visible swelling. NICE NG101 (2025) says to give information about the risk before treatment starts, including how to self-monitor and take baseline measurements; that physical activity does not cause or worsen it; that there is no consistent evidence of increased risk from air travel, hot countries, manicures, hot tubs, sports injuries or from blood tests, injections and blood pressure measurement on the treated side; not to offer compression as a risk-reducing measure; to refer to a specialist lymphoedema service as soon as possible once it develops; and to offer compression therapy as the first stage of management. The NHS calls the treatment decongestive lymphatic therapy: compression, skin care, exercise and specialised massage, followed by a maintenance phase you run yourself. Cellulitis in a swollen arm is the complication to know about, because it needs antibiotics quickly. ${NOT_ADVICE}`,
    links: [BCN_LYMPH, NG101, NHS_LYMPHOEDEMA_TREATMENT, DISIPIO, MAC_LYMPH, CRUK_LYMPH], technologies: ["lymphoedema-decongestive-therapy"], terms: ["lymphadenectomy", "sentinel-lymph-node-biopsy"] }),
  term({ id: "breast-reconstruction", category: "Procedures", name: "Breast reconstruction", aka: ["immediate reconstruction", "delayed reconstruction", "implant reconstruction", "flap reconstruction", "DIEP flap"],
    tldr: "Surgery to make a breast shape after a mastectomy, using an implant, your own tissue from the tummy or back, or both, either during the mastectomy (immediate) or later (delayed). More than one operation is usually needed, and choosing none is a recognised option rather than a failure to decide.",
    summary: `NICE NG101 says to offer breast reconstruction to people after they have had a mastectomy, to be aware that some people may prefer not to have it, to offer both the immediate and the delayed option whether or not they are available locally, and to offer immediate reconstruction to women advised to have a mastectomy including those who may need radiotherapy, unless comorbidities rule out reconstructive surgery. Its table 1 sets out the trade-off: immediate reconstruction gives less time to decide but uses the breast skin already there; delayed gives more time and allows lifestyle changes first; both usually need more than one operation; complications include flap or implant failure, which may leave a flat appearance for a period; implant-based reconstructions may be more affected by radiotherapy than flap reconstructions; and there are no clear differences in satisfaction with completed reconstructions. Cancer Research UK says the new breast will feel and look different to the one removed, that recovery is longer than after mastectomy alone, that further minor surgery such as nipple reconstruction is likely, that surgery to the other breast to match is common, and that in the NHS implant reconstruction for men is not done routinely. After breast-conserving surgery a dent can sometimes be filled with a partial reconstruction or the breast reshaped (therapeutic mammoplasty), which still needs radiotherapy afterwards. ${NOT_ADVICE}`,
    links: [NG101, CRUK_RECON, MAC_RECON, NHS_MASTECTOMY], terms: ["mastectomy", "lumpectomy", "body-image-after-breast-surgery"] }),
  term({ id: "numbness-after-breast-surgery", category: "Side effects", name: "Numbness and nerve pain after breast surgery", aka: ["numb armpit", "loss of sensation after mastectomy", "persistent pain after breast cancer surgery"],
    tldr: "Small sensory nerves are cut during breast and armpit surgery, so an area of the upper inner arm, armpit, chest wall or reconstructed breast is often numb, tingly or painful afterwards. Some feeling returns over months; for many people some of it does not, and almost nobody is warned.",
    summary: `Cancer Research UK says you might have numbness, tingling or a shooting pain in the armpit, upper arm, shoulder or chest wall from damage to nerves during surgery, that the nerves usually repair themselves but it can take many weeks or months, and that medicines can help with nerve pain. The size of the problem comes from a Danish national survey: of 3,253 women aged 18 to 70 who answered a questionnaire a median of 26 months after surgery and adjuvant treatment, 1,543 (47 percent) reported pain in the treated area, 201 of them severe; the odds of sensory disturbance were about five times higher after axillary lymph node dissection than after sentinel lymph node dissection (odds ratio 4.97, 95 percent CI 3.92 to 6.30) and five times higher in women aged 18 to 39; and only about 1 in 5 of those in pain had contacted a doctor about it in the previous three months. A reconstructed breast or a spared nipple has little or no sensation, which is a different question from how it looks and worth asking separately. ${NOT_ADVICE}`,
    links: [CRUK_PROBLEMS, GARTNER, CRUK_RECON, NG101], terms: ["mastectomy", "lumpectomy", "lymphadenectomy"] }),
  term({ id: "cording-axillary-web-syndrome", category: "Side effects", name: "Cording (axillary web syndrome)", aka: ["axillary web syndrome", "cords in the armpit", "banding"],
    tldr: "Tight bands of scar tissue that appear in the armpit in the weeks after lymph node surgery and can run down the arm to the elbow, wrist or thumb. They feel like guitar strings under the skin, they hurt and limit movement, and they usually settle within a few months with physiotherapy.",
    summary: `Cancer Research UK says the scar tissue is called cording, banding or axillary web syndrome, that it can feel something like a guitar string and extend down the arm past the elbow, possibly as far as the wrist or thumb, that it is harmless but can be painful and may limit arm movement, and that regular massage helps. It says to tell your breast care nurse, who can refer you to a physiotherapist for massage and stretching exercises, that it usually gets better within a few months, and that anti-inflammatory painkillers may help. NICE NG101 (1.14.19) says to refer people to the physiotherapy department for individual assessment and treatment if they report a persistent reduction in arm and shoulder mobility after breast cancer surgery or radiotherapy. ${NOT_ADVICE}`,
    links: [CRUK_PROBLEMS, NG101], terms: ["lymphadenectomy", "sentinel-lymph-node-biopsy"] }),
  term({ id: "seroma-after-breast-surgery", category: "Side effects", name: "Seroma after breast surgery", aka: ["fluid collection after breast surgery", "seroma"],
    tldr: "A collection of clear fluid under the wound or in the armpit after breast or lymph node surgery. It is common, it is not an infection, and it can be drained with a needle if it is uncomfortable, though it often comes back and settles on its own.",
    summary: `Cancer Research UK lists seroma among the possible problems after mastectomy: fluid collecting around the operation site can cause swelling and pain, a nurse or doctor can drain it with a needle and syringe if it is painful, the fluid can build up again after being drained, and you should tell your doctor or nurse if you think one is developing. It distinguishes this from a haematoma, where blood collects in the tissues and the area feels hard, and from wound infection, whose signs it gives as a temperature above 37.5 C or below 36 C, redness or a change in the normal colour of the breast, warmth, pain or swelling, discharge from the wound, feeling cold and shivery, or feeling generally unwell. Those infection signs are the ones that mean the 24-hour advice line rather than waiting. ${NOT_ADVICE}`,
    links: [CRUK_PROBLEMS, NG101], terms: ["mastectomy", "lumpectomy"] }),
  term({ id: "breast-margins-and-re-excision", category: "Pathology", name: "Margins after breast-conserving surgery, and second operations", aka: ["clear margins", "tumour on ink", "re-excision", "further surgery after lumpectomy"],
    tldr: "After conserving surgery a pathologist measures how close the cancer came to the edge of the tissue removed. Cancer at the inked edge means another operation is offered; within 1 mm it is considered; and the threshold was lowered in 2024 specifically to spare people a second operation.",
    summary: `NICE NG101 says to offer further surgery, re-excision or mastectomy as appropriate, where invasive cancer or DCIS is present at the radial margins (tumour on ink, 0 mm); to consider further surgery after conserving surgery for invasive cancer with or without DCIS if tumour cells are present within 1 mm of but not at the radial margins; and to use 2 mm rather than 1 mm as the threshold for DCIS alone. The 2024 committee explained its reasoning plainly: a 1 mm margin is likely to achieve better breast preservation and result in fewer additional surgeries, repeated surgeries negatively affect breast appearance and can have a negative effect on self-esteem, and they are traumatic and can lead to stress, infection, pain and complications. It also noted that rates of further surgery currently vary across the country, and asked units to audit radial margins alongside recurrence. ${NOT_ADVICE}`,
    links: [NG101, MAC_BCS, BCN_SURGERY], terms: ["lumpectomy", "mastectomy"] }),
];

// ---------------------------------------------------------------- supplements onto records other files own
const supplements: SpikeSupplement[] = [
  { id: "lumpectomy", cancers: [CANCER], links: [NG101, VERONESI_20Y, NSABP_B06_20Y, EBCTCG_2011, MAC_BCS],
    notes: [
      "Breast cancer, the long-term comparison with mastectomy. In the Milan trial, 701 women with breast cancers no larger than 2 cm were randomly assigned between 1973 and 1980 to radical (Halsted) mastectomy (349) or quadrantectomy followed by radiotherapy (352). After a median 20 years of follow-up, death from any cause had occurred in 41.2 percent of the radical mastectomy group and 41.7 percent of the conserving surgery group (P equals 1.0), and death from breast cancer in 24.3 and 26.1 percent (P equals 0.8). What differed was the breast: 30 women in the conserving group had a recurrence in the same breast against 8 local recurrences after radical mastectomy, a crude cumulative incidence of 8.8 against 2.3 percent, with no significant difference in contralateral cancers, distant metastases or second primary cancers.",
      "In NSABP B-06, 1,851 women were randomly assigned to total mastectomy, lumpectomy alone, or lumpectomy with breast irradiation, and followed for 20 years. Recurrence in the same breast occurred in 14.3 percent of those given radiotherapy against 39.2 percent of those not (P less than 0.001), and no significant difference was found between the three groups in disease-free survival, distant-disease-free survival or overall survival: the hazard ratio for death was 1.05 (0.90 to 1.23) for lumpectomy alone against total mastectomy and 0.97 (0.83 to 1.14) for lumpectomy with irradiation.",
      "NICE NG101 (1.13.3) says to offer whole-breast radiotherapy to women with invasive breast cancer who have had breast-conserving surgery with clear margins, and (1.13.4, 1.13.5) to consider partial-breast radiotherapy for women aged 50 and over with tumours 3 cm or less that are N0, ER-positive, HER2-negative and grade 1 to 2 who will take endocrine therapy for at least 5 years, telling them that local recurrence at 5 years is equivalent, that the risk beyond 5 years is not yet known, and that late adverse effects may be reduced.",
    ] },
  { id: "mastectomy", cancers: [CANCER], links: [NG101, MAC_MASTECTOMY, NHS_MASTECTOMY, CRUK_RECON],
    notes: [
      "When a mastectomy is recommended rather than chosen. Macmillan says surgeons try to do an operation that means you can keep your breast, and that a mastectomy may be recommended when the lump is large compared to the rest of the breast, when there is cancer in different parts of the breast (multicentric), when there is widespread DCIS, when the cancer is on the skin or in the underlying muscle, when you have had radiotherapy to the chest before to treat another cancer, or when you have a family history and have tested positive for a gene mutation.",
      "A mastectomy does not always avoid radiotherapy. NICE NG101 (1.13.10) says to offer adjuvant postmastectomy radiotherapy to people with node-positive (macrometastases) invasive breast cancer or involved resection margins, (1.13.11) to consider it for node-negative T3 or T4 disease, and (1.13.12) not to offer it to people at low risk of local recurrence, for example most people with lymph node-negative breast cancer.",
      "NICE NG101 (1.5.1) says to offer breast reconstruction to people after they have had a mastectomy for breast cancer, and (1.5.2) to be aware that some people may prefer not to have it. Cancer Research UK says a surgeon may be able to improve the appearance of the chest with further surgery after a mastectomy, and that a prosthesis is an alternative to reconstruction.",
    ] },
  { id: "sentinel-lymph-node-biopsy", cancers: [CANCER], links: [NG101, MAC_NODES, DISIPIO, INSEMA],
    notes: [
      "Breast cancer: NICE NG101 (1.4.9) says to stage the axilla with sentinel lymph node biopsy rather than axillary lymph node clearance for people with invasive breast cancer who have no evidence of lymph node involvement on ultrasound or a negative ultrasound-guided needle biopsy, and (1.4.10) to perform it using the dual technique with isotope and blue dye. Macmillan says surgeons remove the smallest number of nodes possible, usually 1 to 3, which reduces the risk of arm swelling and shoulder stiffness.",
      "What it saves. In the pooled prospective cohorts of the DiSipio meta-analysis, arm lymphoedema affected 5.6 percent of women after sentinel node biopsy against 19.9 percent after axillary lymph node dissection.",
      "Where even a sentinel node biopsy may be avoidable. In INSEMA, 4,858 patients in the per-protocol analysis with clinically node-negative T1 or T2 cancer having breast-conserving surgery were randomised between omitting axillary surgery and sentinel node biopsy; 5-year invasive disease-free survival was 91.9 percent with omission and 91.7 percent with surgery (hazard ratio 0.91), and the omission group had less lymphoedema, greater arm mobility and less pain on moving the arm or shoulder. This is a trial result rather than a UK recommendation, and NG101 still asks for sentinel node biopsy.",
    ] },
  { id: "lymphadenectomy", cancers: [CANCER], links: [NG101, AMAROS_10Y, Z0011_10Y, SENOMAC, DISIPIO],
    notes: [
      "Breast cancer, the axilla: NICE NG101 (1.4.11) says to offer axillary node clearance to people whose preoperative ultrasound-guided needle biopsy proved lymph node metastases, (1.4.12) to offer further axillary treatment (clearance or radiotherapy) after a sentinel node biopsy showing 1 or more macrometastasis, (1.4.13) to discuss the benefits and risks of no further treatment with women who have 1 or 2 macrometastases after breast-conserving surgery and have been advised to have whole-breast radiotherapy with systemic therapy, (1.4.14) not to offer further treatment for micrometastases alone, and (1.4.15) to classify isolated tumour cells as lymph node-negative.",
      "Radiotherapy instead of clearance: in the 10-year analysis of AMAROS, 1,425 patients with a positive sentinel node were randomised to axillary lymph node dissection (744) or axillary radiotherapy (681); the 10-year cumulative axillary recurrence was 0.93 percent after dissection and 1.82 percent after radiotherapy, with no difference in overall or disease-free survival, and lymphoedema at 5 years was 24.5 percent after dissection against 11.9 percent after radiotherapy.",
      "Leaving the axilla alone after a positive sentinel node: in ACOSOG Z0011, 891 women with T1 or T2 cancer, no palpable adenopathy and 1 or 2 positive sentinel nodes, all having lumpectomy with tangential whole-breast radiotherapy, had a 10-year overall survival of 86.3 percent with sentinel node dissection alone against 83.6 percent with axillary dissection (non-inferior). In SENOMAC, 2,540 patients in the per-protocol analysis with 1 or 2 sentinel-node macrometastases, about 90 percent of whom had nodal radiotherapy, had a 5-year recurrence-free survival of 89.7 percent without completion dissection against 88.7 percent with it.",
    ] },
  { id: "lymphoedema-decongestive-therapy", cancers: [CANCER], links: [NG101, NHS_LYMPHOEDEMA_TREATMENT, BCN_LYMPH],
    notes: [
      "Breast cancer: NICE NG101 rewrote its lymphoedema recommendations in 2025. It says to refer people who develop it to a specialist lymphoedema service as soon as possible (1.14.6); to assess for other treatable underlying factors such as nodal disease and cellulitis before starting any management programme (1.14.8); to offer compression therapy as the first stage of management, with a shared decision about the form (1.14.9); that kinesiology tape may be tried if compression is not appropriate or comfortable (1.14.10); and to reassure people that physical activity will not worsen their lymphoedema and may improve quality of life (1.14.11). It made no recommendation on manual lymphatic drainage, because the clinical evidence was uncertain and the treatment is labour-intensive.",
      "The NHS describes the treatment as decongestive lymphatic therapy: compression bandages or garments, skin care to reduce the chance of infection, exercises that use the muscles of the affected limb to improve drainage, and specialised massage, followed by a maintenance phase you run yourself with self-massage, garments, exercise and skin care.",
      "NICE NG101 (1.14.4) says not to offer compression therapy as a risk-reducing measure to people who are only at risk, which is a different question from treating lymphoedema that has developed; and (1.14.7) that people who have it should be told how to recognise the serious complications that need urgent medical attention, for example cellulitis or deep vein thrombosis.",
    ] },
  { id: "fertility-preservation", cancers: [CANCER], links: [NG257_FP, NG101, CRUK_FERTILITY, MAC_FERTILITY, POEMS, LAMBERTINI],
    notes: [
      "Breast cancer in the UK: NICE NG101 (1.1.5) sends fertility preservation to the NICE fertility guideline, now NG257 (2026). NG257 (1.53.1) says to discuss fertility preservation with people preparing for medical treatment likely to impair their fertility, and that for people who need urgent treatment this discussion should take place at the earliest possible opportunity; (1.53.5) to offer sperm cryopreservation and (1.53.6) oocyte or embryo cryopreservation to people of reproductive age; and (1.53.7) to consider ovarian tissue cryopreservation where those are not feasible.",
      "The funding sentence most people are never told: NG257 (1.53.3) says that for NHS-funded fertility preservation, do not apply the eligibility criteria used for conventional fertility treatment, including the lower age limit. NG257 (1.53.4) adds that those criteria will apply when it comes to using the stored material, and (1.53.8) that storage is reviewed at least every 5 years with continued NHS funding for people who remain at significant risk of infertility.",
      "Timing and the alternative. Cancer Research UK says egg collection and freezing takes about 2 to 3 weeks, that letrozole or tamoxifen can be combined with lower-dose IVF hormones, and that IVF is available for some people on the NHS but not in all parts of the country. Where there is no time, switching the ovaries off during chemotherapy is the other route: in an individual patient-level meta-analysis of 873 patients from five trials, premature ovarian insufficiency occurred in 14.1 percent given a GnRH agonist against 30.9 percent of controls (adjusted odds ratio 0.38) and post-treatment pregnancy in 10.3 against 5.5 percent, with no significant difference in disease-free or overall survival.",
    ] },
  { id: "scalp-cooling", cancers: [CANCER], links: [NANGIA, DILAWARI, MAC_HAIR],
    notes: [
      "Breast cancer, the equity gap in the evidence. A phase II feasibility study of the Paxman scalp cooling device planned to enrol 30 Black patients receiving chemotherapy for stage I to III breast cancer and closed early after 15, for lack of efficacy: median hair loss and alopecia distress scores both rose during cooling, most participants stopped before finishing chemotherapy because of grade 3 alopecia, and only one avoided significant hair loss. The authors concluded that scalp cooling may not be efficacious in preventing alopecia in Black women, and pointed to differences in hair thickness and volume and to limitations of cap design. The randomised evidence that supports scalp cooling, including the SCALP trial, did not include enough Black participants to answer the question.",
      "Practicalities worth asking about before the first cycle: cooling adds time at each end of the infusion, so a treatment day gets longer, and availability varies by unit. Macmillan says a wig is easier to match if it is obtained before treatment starts, that eyebrows and eyelashes can go too and it helps to buy and practise with products beforehand, and that the Little Princess Trust provides free real-hair wigs to people up to the age of 24.",
    ] },
  { id: "hair-loss-and-scalp-cooling-breast", cancers: [CANCER], links: [DILAWARI],
    notes: ["Whose hair the evidence describes. The randomised and cohort figures for scalp cooling come from trials with few Black participants. A later phase II study of the Paxman device in Black patients having chemotherapy for stage I to III breast cancer closed early after 15 of a planned 30 participants for lack of efficacy, with only one avoiding significant hair loss, and its authors named hair thickness, hair volume and cap design as the likely reasons. Anyone quoting a success rate of about one in two should say which population it came from."] },
  { id: "menopause-after-chemotherapy-breast", cancers: [CANCER], links: [NG101, CRUK_MENOPAUSE, NHS_MENOPAUSE],
    notes: [
      "Whichever receptor result comes back, NICE NG101 (1.14.20) says to offer women information and counselling about the possibility of early menopause and menopausal symptoms associated with breast cancer treatment, and (1.14.21) to stop systemic HRT in women who are diagnosed with breast cancer.",
      "Bone health follows the menopause. NICE NG101 (1.14.26) says to offer a baseline DEXA scan to women with invasive breast cancer who are not receiving adjuvant bisphosphonates and who are starting an aromatase inhibitor, have treatment-induced menopause, or are starting ovarian ablation or suppression; (1.14.27) not to offer a DEXA scan to people receiving tamoxifen alone; and (1.14.28) to offer bisphosphonates to women identified by the UK expert group algorithms on treatment-induced bone loss.",
    ] },
  { id: "body-image-after-breast-surgery", cancers: [CANCER], links: [GARTNER, CRUK_PROBLEMS, CRUK_AFTER_SURGERY],
    notes: [
      "Sensation, which is a separate question from appearance and is asked far less often. Cancer Research UK says nerve damage during surgery can leave numbness, tingling or shooting pain in the armpit, upper arm, shoulder or chest wall, and that the nerves usually repair themselves but it can take many weeks or months. In a Danish national survey of 3,253 women a median of 26 months after breast cancer surgery, 47 percent reported pain in the treated area, and the odds of sensory disturbance were about five times higher after axillary lymph node dissection than after sentinel lymph node dissection.",
      "A reconstructed breast or a spared nipple has little or no feeling, whatever it looks like. Cancer Research UK says the new breast will feel and look different to the one removed, so asking specifically about sensation before the operation is how this gets discussed rather than discovered.",
    ] },
  { id: "neutropenic-sepsis-breast-chemotherapy", cancers: [CANCER],
    notes: ["This applies to chemotherapy for any type of breast cancer, not only triple-negative disease: the temperature rule and the 999 list do not change with the receptor result."] },
  { id: "work-and-money-breast-cancer-uk", cancers: [CANCER] },
  { id: "carers-breast-cancer-uk", cancers: [CANCER] },
];

